"use client"

import * as React from "react"
import { motion } from "motion/react"
import { Slot } from "@radix-ui/react-slot"
import { cn } from "@/lib/utils"
import { buttonVariants } from "../shared/button.variants"
import { type ButtonProps } from "../shared/button.types"

function ButtonSpinner({ className }: { className?: string }) {
  return (
    <svg
      className={cn("animate-spin", className)}
      xmlns="http://www.w3.org/2000/svg"
      fill="none"
      viewBox="0 0 24 24"
      aria-hidden="true"
    >
      <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="3" />
      <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z" />
    </svg>
  )
}

const MotionComp = motion.create("button")

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(({
  className,
  variant,
  color,
  size,
  radius,
  isIconOnly,
  asChild = false,
  isLoading = false,
  loadingContent,
  startContent,
  endContent,
  children,
  disabled,
  ...props
}, ref) => {
  if (asChild) {
    return (
      <Slot
        ref={ref}
        data-slot="button"
        className={cn(
          buttonVariants({ variant, size, color, radius, isIconOnly }),
          className
        )}
        {...props}
      >
        {children}
      </Slot>
    )
  }

  const spinnerSize = size === "sm" ? "size-3" : size === "lg" ? "size-5" : "size-4"

  return (
    <MotionComp
      ref={ref}
      data-slot="button"
      disabled={disabled || isLoading}
      aria-busy={isLoading}
      className={cn(
        buttonVariants({ variant, size, color, radius, isIconOnly }),
        "active:scale-100" // disable CSS tap scale since we use spring scaling
      )}
      whileTap={{ scale: 0.96 }}
      transition={{ type: "spring", stiffness: 500, damping: 25 }}
      {...(props as any)}
    >
      {isLoading ? (
        <>
          <ButtonSpinner className={spinnerSize} />
          {loadingContent ?? (!isIconOnly && children)}
        </>
      ) : (
        <>
          {startContent}
          {children}
          {endContent}
        </>
      )}
    </MotionComp>
  )
})
Button.displayName = "Button"

export { Button, buttonVariants }

import * as React from "react"
import { type VariantProps } from "class-variance-authority"
import { buttonVariants } from "./button.variants"

export type ButtonVariantProps = VariantProps<typeof buttonVariants>;

export type ButtonBaseProps = Omit<
  React.ButtonHTMLAttributes<HTMLButtonElement>,
  keyof ButtonVariantProps
>;

export interface ButtonProps
  extends ButtonBaseProps,
    ButtonVariantProps {
  asChild?: boolean;
  isLoading?: boolean;
  loadingContent?: React.ReactNode;
  startContent?: React.ReactNode;
  endContent?: React.ReactNode;
}

import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"
import {
  surfaceVariants,
  fujinSurfaceStyle,
  type SurfaceVariantProps,
  type FujinSurfaceVars,
} from "@/lib/fujin-variants"

// ─── Card CVA Variants ────────────────────────────────────────────────────────

const cardVariants = cva(
  [
    // Base layout
    "flex flex-col relative overflow-hidden transition-all duration-200 ease-out text-card-foreground",
  ],
  {
    variants: {
      // ── Semantic Prominence (HeroUI v3) ──────────────────────────
      variant: {
        default: "",
        transparent: "bg-transparent border-transparent shadow-none!",
        secondary: "bg-fujin-default/30 border-fujin-default/40",
        tertiary: "bg-fujin-default/50 border-fujin-default/60",
      },
      // ── Shadow Prominence ───────────────────────────────────────
      shadow: {
        none: "shadow-none",
        sm: "shadow-sm",
        md: "shadow-md",
        lg: "shadow-lg",
      },
      // ── Card Radius ─────────────────────────────────────────────
      radius: {
        none: "rounded-none",
        sm: "rounded-md",
        md: "rounded-xl",
        lg: "rounded-2xl",
      },
      // ── Hover interaction zoom & shadow offset ──────────────────
      isHoverable: {
        true: "hover:-translate-y-1 hover:shadow-lg hover:border-border/80",
        false: "",
      },
      // ── Press interaction scaling effect ────────────────────────
      isPressable: {
        true: "cursor-pointer active:scale-[0.98] select-none",
        false: "",
      },
    },
    defaultVariants: {
      variant: "default",
      shadow: "md",
      radius: "md",
      isHoverable: false,
      isPressable: false,
    },
  }
)

// ─── Types ───────────────────────────────────────────────────────────────────

export interface CardProps
  extends React.ComponentProps<"div">,
    VariantProps<typeof cardVariants>,
    SurfaceVariantProps {
  /** Escape hatch: override any individual glass/surface token for this instance only. */
  vars?: FujinSurfaceVars
}

// ─── Card Wrapper Component ──────────────────────────────────────────────────

const Card = React.forwardRef<HTMLDivElement, CardProps>(
  (
    {
      className,
      variant = "default",
      shadow = "md",
      radius = "md",
      isHoverable = false,
      isPressable = false,
      intensity,
      interactive,
      vars,
      style,
      ...props
    },
    ref
  ) => {
    const isGlass = variant !== "transparent";

    // Convert card radius configuration to fujin surface variables
    const radiusVars = radius === "none"
      ? { "--fujin-radius": "0px" }
      : radius === "sm"
      ? { "--fujin-radius": "var(--radius-sm)" }
      : radius === "md"
      ? { "--fujin-radius": "var(--radius-md)" }
      : { "--fujin-radius": "var(--radius-lg)" };

    return (
      <div
        ref={ref}
        data-slot="card"
        className={cn(
          isGlass && surfaceVariants({ intensity, interactive: interactive ?? isHoverable }),
          cardVariants({ variant, shadow, radius, isHoverable, isPressable }),
          className
        )}
        style={{
          ...fujinSurfaceStyle(vars),
          ...radiusVars,
          ...style,
        }}
        {...props}
      />
    )
  }
)
Card.displayName = "Card"

// ─── Card Subcomponents ──────────────────────────────────────────────────────

function CardHeader({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card-header"
      className={cn(
        "@container/card-header grid auto-rows-min grid-rows-[auto_auto] items-start gap-1.5 px-6 py-4 has-data-[slot=card-action]:grid-cols-[1fr_auto] [.border-b]:pb-4",
        className
      )}
      {...props}
    />
  )
}

function CardTitle({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card-title"
      className={cn("leading-none font-semibold text-lg", className)}
      {...props}
    />
  )
}

function CardDescription({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card-description"
      className={cn("text-muted-foreground text-sm", className)}
      {...props}
    />
  )
}

function CardAction({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card-action"
      className={cn(
